function validate([nums, queries]) {
  if (nums.length < 1 || nums.length > 2000) return 'nums needs 1 to 2000 values.';
  if (nums.some(v => v < 0 || v > 2147483647)) return 'Each value of nums is between 0 and 2^31 - 1.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs at least one query.';
  for (const query of queries) {
    if (query.length !== 2) return 'Each query is a pair [l, r].';
    if (query[0] < 0 || query[0] > query[1] || query[1] >= nums.length) return 'Each query needs 0 <= l <= r <= nums.length - 1.';
  }
  return null;
}

