function maximumSubarrayXor(nums, queries) {
  const n = nums.length;
  const byLeft = Array.from({ length: n }, () => []);
  for (let k = 0; k < queries.length; k++) {
    byLeft[queries[k][0]].push(k);
  }
  const score = new Array(n).fill(0);
  const best = new Array(n).fill(0);
  const answer = new Array(queries.length).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    score[i] = nums[i];
    best[i] = nums[i];
    for (let j = i + 1; j < n; j++) {
      score[j] = score[j - 1] ^ score[j];
      best[j] = Math.max(best[j - 1], best[j], score[j]);
    }
    for (const k of byLeft[i]) {
      answer[k] = best[queries[k][1]];
    }
  }
  return answer;
}

