function maximumSubarrayXor(nums, queries) {
  // Play the shrinking rounds literally on every subarray inside each query's range.
  const xorScore = (values) => {
    let current = values.slice();
    while (current.length > 1) {
      const next = [];
      for (let t = 0; t + 1 < current.length; t++) next.push(current[t] ^ current[t + 1]);
      current = next;
    }
    return current[0];
  };
  return queries.map(([l, r]) => {
    let top = -1;
    for (let a = l; a <= r; a++)
      for (let b = a; b <= r; b++) top = Math.max(top, xorScore(nums.slice(a, b + 1)));
    return top;
  });
}

