function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  // Few bits make values repeat and cancel under XOR; 31 bits use the whole allowed range.
  const bits = large ? [31, 12, 3][Math.floor(rand() * 3)] : [1, 2, 4, 31][Math.floor(rand() * 4)];
  const nums = Array.from({ length: n }, () => Math.floor(rand() * 2 ** bits));
  const q = large ? 2000 : 1 + Math.floor(rand() * 6);
  const queries = Array.from({ length: q }, () => {
    const a = Math.floor(rand() * n);
    const b = Math.floor(rand() * n);
    return [Math.min(a, b), Math.max(a, b)];
  });
  return [nums, queries];
}
